UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Angioedema — Initial Assessment","body":"[Angioedema Steps Summary](#/info/angio-steps-summary)\n\n~110,000 ED visits/year in the US. Up to 44% of patients with hereditary angioedema (HAE) are initially misdiagnosed. The critical first step is a structured airway assessment before mechanism classification. [1][5][7]\n\nUse the airway-risk tool when the patient is not an obvious immediate airway. It combines hard airway triggers, Ishoo anatomic staging, and the 2023 AJEM ED intubation-risk score. [7][8][26]\n\n[Angioedema Airway Risk Calculator](#/calculator/angio-airway-risk)\n\nAssess for voice change, hoarseness, stridor, dyspnea, drooling, secretion intolerance, tongue/floor-of-mouth edema, pharyngeal edema, laryngeal edema, progression in the ED, and ability to tolerate supine positioning.","citation":[1,5,7,8,26],"options":[{"label":"Immediate Airway Threat","description":"Stridor, hypoxemia, secretion failure, rapidly progressive voice/laryngeal symptoms","next":"angio-airway-secure","urgency":"critical"},{"label":"Run Objective Airway Risk","description":"Stable enough to score, but not clearly low-risk","next":"angio-airway-risk-tree"},{"label":"Clearly Low-Risk Peripheral Edema","description":"Lip/facial edema only, no voice, dyspnea, drooling, tongue, pharyngeal, or laryngeal involvement","next":"angio-classify"}],"calculatorLinks":[{"id":"angio-airway-risk","label":"Angioedema Airway Risk"}],"summary":"~110K ED visits/year, 44% HAE initially misdiagnosed - first run structured airway risk before classification"}'::jsonb
WHERE id = 'angio-start' AND tree_id = 'angioedema';

