-- Node: angio-airway-secure (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Secure the Airway","body":"**DUAL SETUP: intubation + cricothyrotomy ready simultaneously.** Call the most experienced airway operator early. Notify anesthesia/ENT/trauma airway when available. Keep the patient upright and spontaneously breathing if oxygenation allows. [9][27]\n\n**High-risk features requiring definitive airway planning:** stridor, hypoxemia, secretion intolerance/drooling, shortness of breath, voice change/hoarseness with progression, pharyngeal edema, posterior tongue/floor-of-mouth edema, laryngeal edema on scope, altered mental status, exhaustion, or AJEM score >7. [5][26][27]\n\n**Preferred approach:** awake flexible endoscopic or awake video-assisted technique with topical lidocaine and surgical airway backup. Do NOT paralyze until the airway anatomy is visualized and a viable rescue plan is ready unless the patient is crashing. Nasotracheal route may bypass lingual swelling in selected patients; NEAR angioedema data reported higher first-attempt success with nasotracheal than orotracheal intubation. [9]\n\n**[Awake Intubation](#/tree/awake-intubation)** (see Airway category)\n\n**Extubation:** Wait for visible improvement of edema. Extubate over airway exchange catheter. Video laryngoscopy or flexible scope to confirm laryngeal edema resolution. Cuff leak may provide adjunctive info.","citation":[5,9,26,27],"next":"angio-classify","calculatorLinks":[{"id":"angio-airway-risk","label":"Angioedema Airway Risk"}],"summary":"Dual setup: intubation + cric ready; awake flexible/video approach preferred when oxygenation allows; avoid paralysis until anatomy and rescue plan are clear","safetyLevel":"critical"}'::jsonb
WHERE id = 'angio-airway-secure' AND tree_id = 'angioedema';

-- Node: angio-airway-monitor (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Airway Monitoring","body":"**Supplemental O2, continuous monitoring, and q15 minute airway reassessment until clearly improving.** Do NOT rely on NIPPV (CPAP/BiPAP) because it does not treat a supraglottic/anatomic obstruction and can delay definitive airway control. [5][27]\n\n[Angioedema Airway Risk Calculator](#/calculator/angio-airway-risk)\n\n**Moderate-risk watch group:** AJEM score 5-7, stage 3 tongue/floor-of-mouth edema, progressive symptoms, pharyngeal edema, dyspnea without current distress, bradykinin mechanism with head/neck involvement, or inability to confidently exclude laryngeal edema. [7][8][26]\n\n**Monitoring plan:** senior airway operator aware, airway cart and cric tray immediately available, consider flexible laryngoscopy if available, avoid transport away from airway backup unless necessary, and re-score after treatment. Escalate immediately for voice progression, drooling, dyspnea, stridor, hypoxemia, worsening tongue/floor-of-mouth swelling, or score rising above 7.\n\n**KEY:** isolated lip/facial edema without tongue, pharyngeal, dyspnea, voice, drooling, or laryngeal involvement is low risk for intubation. [7][8][26]","citation":[5,7,8,26,27],"next":"angio-classify","calculatorLinks":[{"id":"angio-airway-risk","label":"Angioedema Airway Risk"}],"summary":"Moderate-risk airway watch: q15 min reassessment, airway backup ready, scope if available, escalate for symptom progression or score >7"}'::jsonb
WHERE id = 'angio-airway-monitor' AND tree_id = 'angioedema';

