UPDATE decision_nodes SET data = '{"type":"question","module":6,"title":"Disposition — Ishoo Staging","body":"Disposition should combine anatomic location, trajectory during observation, mechanism, and the objective airway-risk score. [4][7][8][26]\n\n[Ishoo Staging & Disposition Guide](#/info/angio-ishoo-staging)\n[Angioedema Airway Risk Calculator](#/calculator/angio-airway-risk)\n\n**Modified Ishoo Staging:**\n• **Stage 1:** Facial rash, facial edema, lip edema\n• **Stage 2:** Soft palate edema\n• **Stage 3:** Tongue edema, floor of mouth edema\n• **Stage 4:** Laryngeal edema (voice change, stridor)\n\nAll patients need strict return precautions and PCP follow-up. Discharge is appropriate only after stable/improving symptoms, no airway warning signs, ability to tolerate oral intake, and reliable return precautions. [4][5]","citation":[4,5,7,8,26],"options":[{"label":"Stage 1-2: Face / Lip / Soft Palate","description":"Peripheral edema without tongue or laryngeal involvement","next":"angio-dispo-mild"},{"label":"Stage 3: Tongue / Floor of Mouth","description":"Higher risk for airway progression","next":"angio-dispo-admit","urgency":"urgent"},{"label":"Stage 4: Laryngeal Involvement","description":"Voice change, stridor, or confirmed laryngeal edema","next":"angio-dispo-icu","urgency":"critical"}],"calculatorLinks":[{"id":"angio-airway-risk","label":"Angioedema Airway Risk"}],"summary":"Disposition: stage 1-2 and low score may discharge after observation; stage 3 or moderate score admit/observe closely; stage 4 or high score ICU/airway"}'::jsonb
